package com.pbexporter;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

final class AdventureLogParser
{
	private static final String TEAM_SIZES = "(?<teamsize>\\d+(?:\\+|-\\d+)? players?|Solo)";

	private static final String PB_LABEL_BODY =
		"Fastest (?:kill|run|Room time)"
			+ "(?: - \\(Team size: \\(?" + TEAM_SIZES + "(?: [A-Za-z ]+)?\\)\\)?)?";

	private static final Pattern PB_LINE = Pattern.compile(PB_LABEL_BODY + ":\\s*(?<time>[0-9:]+(?:\\.[0-9]+)?)");
	private static final Pattern PB_LABEL = Pattern.compile(PB_LABEL_BODY + ":\\s*$");
	private static final Pattern BARE_TIME = Pattern.compile("^[0-9:]+(?:\\.[0-9]+)?$");
	private static final Pattern IGNORED_LINE = Pattern.compile("^Fastest (?:Overall|Wave) time|\\(former\\)");

	private static final String[] RAID_PREFIXES = {
		"chambers of xeric",
		"theatre of blood",
		"tombs of amascut"
	};

	static final String TFA_BOSS = "the fractured archive";

	private static final Pattern TFA_ROW = Pattern.compile("^\\d+ Players?$", Pattern.CASE_INSENSITIVE);

	private static final class Pending
	{
		final boolean wanted;
		final String scale;

		Pending(boolean wanted, String scale)
		{
			this.wanted = wanted;
			this.scale = scale;
		}
	}

	static final class Result
	{
		final List<PbRecord> records = new ArrayList<>();
		final Set<String> bosses = new LinkedHashSet<>();
		final List<String> skipped = new ArrayList<>();
	}

	private AdventureLogParser()
	{
	}

	static Result parse(List<String> lines)
	{
		Result result = new Result();
		Map<String, PbRecord> unique = new LinkedHashMap<>();

		String header = null;
		Pending pending = null;
		for (String raw : lines)
		{
			String line = raw == null ? "" : raw.trim();

			if (line.isEmpty())
			{
				header = null;
				pending = null;
				continue;
			}

			if (header == null)
			{
				header = line;
				continue;
			}

			String boss = normalizeBoss(header);
			if (!isRaid(boss))
			{
				continue; // not a raid
			}

			if (BARE_TIME.matcher(line).matches())
			{
				if (pending == null)
				{
					result.skipped.add(header + " | " + line);
					continue;
				}

				Double value = parseSeconds(line);
				if (pending.wanted && value != null)
				{
					unique.put(boss + "\n" + pending.scale, new PbRecord(boss, pending.scale, value));
					result.bosses.add(boss);
				}
				pending = null;
				continue;
			}

			if (IGNORED_LINE.matcher(line).find())
			{
				pending = line.endsWith(":") ? new Pending(false, null) : null;
				continue;
			}

			Matcher label = PB_LABEL.matcher(line);
			if (label.find())
			{
				pending = new Pending(true, normalizeScale(label.group("teamsize")));
				continue;
			}
			pending = null;

			Matcher matcher = PB_LINE.matcher(line);
			if (!matcher.find())
			{
				result.skipped.add(header + " | " + line);
				continue;
			}

			Double seconds = parseSeconds(matcher.group("time"));
			if (seconds == null)
			{
				result.skipped.add(header + " | " + line);
				continue;
			}

			String scale = normalizeScale(matcher.group("teamsize"));
			unique.put(boss + "\n" + scale, new PbRecord(boss, scale, seconds));
			result.bosses.add(boss);
		}

		result.records.addAll(unique.values());
		return result;
	}

	static boolean isRaid(String boss)
	{
		for (String prefix : RAID_PREFIXES)
		{
			if (boss.startsWith(prefix))
			{
				return true;
			}
		}
		return false;
	}

	static List<PbRecord> parseAllianceLog(List<String> texts)
	{
		int start = texts.indexOf("Completion Time");
		if (start < 0 || !texts.contains("Overall"))
		{
			return null;
		}

		List<PbRecord> records = new ArrayList<>();
		for (int i = start + 1; i + 1 < texts.size(); i++)
		{
			if (!TFA_ROW.matcher(texts.get(i)).matches())
			{
				continue;
			}

			Double seconds = parseSeconds(texts.get(i + 1));
			if (seconds != null)
			{
				records.add(new PbRecord(TFA_BOSS, normalizeScale(texts.get(i)), seconds));
			}
		}
		return records;
	}

	static String normalizeBoss(String header)
	{
		return header
			.replace('\u00a0', ' ')
			.replace('\u2019', '\'')
			.replace(":", "")
			.trim()
			.toLowerCase(Locale.ROOT)
			.replaceAll("\\s+", " ")
			.replaceAll(" - (hard|expert|entry|challenge)(?: mode)?$", " $1 mode");
	}

	static String normalizeScale(String teamSize)
	{
		if (teamSize == null)
		{
			return null;
		}

		String scale = teamSize.trim().toLowerCase(Locale.ROOT);
		if (scale.equals("solo") || scale.equals("1 player"))
		{
			return "solo";
		}
		if (scale.endsWith("player"))
		{
			return scale + "s";
		}
		return scale;
	}

	static Double parseSeconds(String text)
	{
		try
		{
			String[] parts = text.split(":");
			double seconds;
			if (parts.length == 3)
			{
				seconds = Integer.parseInt(parts[0]) * 3600
					+ Integer.parseInt(parts[1]) * 60
					+ Double.parseDouble(parts[2]);
			}
			else if (parts.length == 2)
			{
				seconds = Integer.parseInt(parts[0]) * 60
					+ Double.parseDouble(parts[1]);
			}
			else if (parts.length == 1)
			{
				seconds = Double.parseDouble(parts[0]);
			}
			else
			{
				return null;
			}
			return Math.round(seconds * 100) / 100.0;
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}
}

package com.pbexporter;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(PbExporterConfig.GROUP)
public interface PbExporterConfig extends Config
{
	String GROUP = "pbexporter";

	@ConfigItem(
		keyName = "serverUrl",
		name = "Server URL",
		description = "Server URL for submitting Personal Bests",
		position = 0
	)
	default String serverUrl()
	{
		return "";
	}

	@ConfigItem(
		keyName = "apiToken",
		name = "API Token",
		description = "Personal token for server authentication",
		position = 1,
		secret = true
	)
	default String apiToken()
	{
		return "";
	}

	@ConfigItem(
		keyName = "copyRawData",
		name = "Copy raw data",
		description = "Copy Personal Bests to clipboard in JSON format",
		position = 2
	)
	default boolean copyRawData()
	{
		return false;
	}
}

package com.pbexporter;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
