@Slf4j
@PluginDescriptor(
	name = "PB Exporter",
	internalName = "pb-exporter",
	legacyDataDirectory = "pb-exporter",
	description = "Exports RuneLite Personal Bests to the clipboard or a remote server",
	tags = {"pb", "personal best", "export"}
)
public class PbExporterPlugin extends Plugin
{
	private static final MediaType JSON = MediaType.get("application/json; charset=utf-8");
	private static final long UPLOAD_COOLDOWN_MS = TimeUnit.HOURS.toMillis(3);
	private static final String LAST_UPLOAD_PREFIX = "lastUpload.";
	private static final Pattern ADVENTURE_LOG_TITLE_PATTERN = Pattern.compile("The Exploits of (.+)");

	private static final boolean ADV_LOG_DIAGNOSTICS = false;

	// how many game ticks the Alliance Log is read after it was opened (the table is filled in by scripts)
	private static final int TFA_POLL_TICKS = 12;

	private static final Pattern SCALE_PATTERN = Pattern.compile(
		"^(?<boss>.+?)\\s+(?<scale>solo|\\d+(?:\\+|-\\d+)? players?)$",
		Pattern.CASE_INSENSITIVE
	);

	private static final Map<String, List<String>> EXPORT_LIST = new LinkedHashMap<>();

	static
	{
		bosses("tztok-jad", "tzkal-zuk");
		for (String n : new String[]{"first", "second", "third", "fourth", "fifth", "sixth"})
		{
			bosses("tzhaar-ket-rak's " + n + " challenge");
		}
		bosses("sol heredit", "phosani's nightmare", "gauntlet", "corrupted gauntlet", "yama",
				"amoxliatl", "mad angel", "royal titans", "vorkath", "zulrah", "phantom muspah", "maggot king",
				"duke sucellus", "leviathan", "vardorvis", "whisperer",
				"duke sucellus (awakened)", "leviathan (awakened)", "vardorvis (awakened)", "whisperer (awakened)",
				"demonic brutus",
				"shellbane gryphon", "grotesque guardians", "araxxor", "alchemical hydra",
				"hespori", "mimic", "galvek", "fragment of seren");

		raid("theatre of blood", "hard mode", "solo", "2 players", "3 players", "4 players", "5 players");
		raid("chambers of xeric", "challenge mode", "solo", "3 players", "5 players");
		raid("tombs of amascut", "expert mode", "solo", "2 players", "3 players", "4 players", "8 players");
		put("nightmare", "solo", "5 players");
		put("the fractured archive", scales(true, 2, 8));
	}

	private static void bosses(String... names)
	{
		for (String name : names)
		{
			EXPORT_LIST.put(name, Collections.emptyList());
		}
	}

	private static void put(String boss, String... scales)
	{
		EXPORT_LIST.put(boss, Arrays.asList(scales));
	}

	private static void raid(String boss, String hardSuffix, String... scales)
	{
		put(boss, scales);
		put(boss + " " + hardSuffix, scales);
	}

	private static String[] scales(boolean solo, int from, int to)
	{
		List<String> result = new ArrayList<>();
		if (solo)
		{
			result.add("solo");
		}
		for (int i = from; i <= to; i++)
		{
			result.add(i + " players");
		}
		return result.toArray(new String[0]);
	}

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	@Inject
	private PbExporterConfig config;

	@Inject
	private OkHttpClient okHttpClient;

	@Inject
	private Gson gson;

	private volatile Session activeSession;

	@Provides
	PbExporterConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PbExporterConfig.class);
	}

	@Override
	protected void startUp() throws Exception
	{
		Gson exportGson = gson.newBuilder()
			.setPrettyPrinting()
			.disableHtmlEscaping()
			.serializeNulls()
			.create();

		OkHttpClient uploadClient = okHttpClient.newBuilder()
			.followRedirects(false)
			.followSslRedirects(false)
			.callTimeout(30, TimeUnit.SECONDS)
			.build();

		PbStore pbStore = new PbStore(getPluginDirectory(), exportGson);
		ExecutorService ioExecutor = Executors.newSingleThreadExecutor(r ->
		{
			Thread thread = new Thread(r, "pb-exporter-io");
			thread.setDaemon(true);
			return thread;
		});

		Session session = new Session(exportGson, uploadClient, pbStore, ioExecutor);
		activeSession = session;

		clientThread.invokeLater(() ->
		{
			if (activeSession == session)
			{
				initializeSession(session);
			}
		});

		log.info("PB Exporter started");
	}

	@Override
	protected void shutDown()
	{
		Session session = activeSession;
		activeSession = null;

		if (session != null)
		{
			for (Call call : session.uploads.values())
			{
				call.cancel();
			}

			session.ioExecutor.shutdown();
		}

		log.info("PB Exporter stopped");
	}

	private void initializeSession(Session session)
	{
		assert client.isClientThread();

		if (session.initialized)
		{
			return;
		}

		session.initialized = true;
		GameState gameState = client.getGameState();
		session.wasLoggedIn = gameState == GameState.LOGGED_IN;
		session.worldHopInProgress = gameState == GameState.HOPPING;

		if (session.wasLoggedIn)
		{
			cachePlayer(session);
		}
	}

	private Session getClientSession()
	{
		assert client.isClientThread();

		Session session = activeSession;
		if (session != null)
		{
			initializeSession(session);
		}
		return session;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		Session session = getClientSession();
		if (session == null)
		{
			return;
		}

		GameState newState = event.getGameState();
		if (newState == GameState.LOADING || newState == GameState.HOPPING)
		{
			session.pohOwner = null;
		}

		if (newState == GameState.LOGGED_IN)
		{
			session.wasLoggedIn = true;
			session.worldHopInProgress = false;

			if (!cachePlayer(session))
			{
				session.currentNickname = null;
				session.currentRsProfile = null;
			}
			return;
		}

		if (newState == GameState.HOPPING)
		{
			session.worldHopInProgress = true;
			return;
		}

		if (newState == GameState.LOGIN_SCREEN)
		{
			boolean shouldUpload =
				session.wasLoggedIn && !session.worldHopInProgress;
			String nickname = session.currentNickname;
			String rsProfile = session.currentRsProfile;

			session.wasLoggedIn = false;
			session.worldHopInProgress = false;
			session.currentNickname = null;
			session.currentRsProfile = null;

			if (shouldUpload)
			{
				log.debug("PB Exporter: logout detected for {}", nickname);
				uploadPersonalBestsIfAllowed(session, nickname, rsProfile);
			}
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		Session session = getClientSession();
		if (session != null && client.getGameState() == GameState.LOGGED_IN)
		{
			session.wasLoggedIn = true;
			session.worldHopInProgress = false;
			cachePlayer(session);
			processAdventureLog(session);
			processAllianceLog(session);
		}
	}

	private void processAllianceLog(Session session)
	{
		assert client.isClientThread();

		if (session.tfaTicks <= 0)
		{
			return;
		}
		session.tfaTicks--;

		String nickname = session.currentNickname;
		if (nickname == null)
		{
			return;
		}

		List<String> texts = TfaBoard.readTexts(client);
		if (texts == null)
		{
			return;
		}

		List<PbRecord> records = AdventureLogParser.parseAllianceLog(texts);
		if (records == null)
		{
			return;
		}

		String fingerprint = nickname + "|" + records;
		if (!fingerprint.equals(session.tfaSeen))
		{
			session.tfaSeen = fingerprint;
			return;
		}
		session.tfaTicks = 0;

		if (records.isEmpty())
		{
			logAdv("Alliance Log: no personal completion times on the board");
			return;
		}

		PbStore store = session.pbStore;
		logAdv("Alliance Log: saving " + records.size() + " records: " + records);

		try
		{
			session.ioExecutor.execute(() ->
			{
				try
				{
					store.replaceBosses(
						nickname,
						Collections.singleton(AdventureLogParser.TFA_BOSS),
						records
					);
					log.info(
						"PB Exporter: saved {} Fractured Archive times of {} to pbs.json",
						records.size(),
						nickname
					);
				}
				catch (IOException | RuntimeException e)
				{
					log.warn("PB Exporter: could not write pbs.json", e);
				}
			});
		}
		catch (RejectedExecutionException e)
		{
			log.debug("PB Exporter: plugin is shutting down, Alliance Log was not saved");
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		Session session = getClientSession();
		if (session == null)
		{
			return;
		}

		switch (event.getGroupId())
		{
			case InterfaceID.MENU:
			case InterfaceID.MENU_NEW:
				session.advLogLoaded = true;
				break;
			case InterfaceID.JOURNALSCROLL:
				session.scrollLoaded = true;
				break;
			case TfaBoard.GROUP:
				session.tfaTicks = TFA_POLL_TICKS;
				session.tfaSeen = null;
				break;
			default:
				break;
		}
	}

	private void processAdventureLog(Session session)
	{
		assert client.isClientThread();

		if (session.advLogLoaded)
		{
			session.advLogLoaded = false;

			String owner = readAdventureLogOwner();
			if (owner != null)
			{
				session.pohOwner = owner;
				logAdv("Adventure Log of " + owner + " is open");
			}
		}

		if (!session.scrollLoaded)
		{
			return;
		}
		session.scrollLoaded = false;

		String nickname = session.currentNickname;
		if (nickname == null)
		{
			logAdv("scroll ignored: the player name is not cached yet");
			return;
		}

		if (session.pohOwner == null || !normalizeNickname(nickname).equals(normalizeNickname(session.pohOwner)))
		{
			logAdv("scroll ignored: it is not from your own Adventure Log (owner: " + session.pohOwner + ")");
			return;
		}

		List<String> lines = readScrollLines();
		if (lines == null)
		{
			logAdv("scroll ignored: its text widget was not found");
			return;
		}
		logAdv("scroll lines:\n" + String.join("\n", lines));

		AdventureLogParser.Result result = AdventureLogParser.parse(lines);
		if (!result.skipped.isEmpty())
		{
			logAdv("lines that were not recognised as a time: " + result.skipped);
		}
		if (result.records.isEmpty())
		{
			logAdv("nothing to save: no \"Fastest ...\" lines on this scroll");
			return;
		}

		List<PbRecord> records = result.records;
		Set<String> bosses = result.bosses;
		PbStore store = session.pbStore;
		logAdv("saving " + records.size() + " records: " + records);

		try
		{
			session.ioExecutor.execute(() ->
			{
				try
				{
					store.replaceBosses(nickname, bosses, records);
					log.info(
						"PB Exporter: saved {} personal bests of {} to pbs.json",
						records.size(),
						nickname
					);
				}
				catch (IOException | RuntimeException e)
				{
					log.warn("PB Exporter: could not write pbs.json", e);
				}
			});
		}
		catch (RejectedExecutionException e)
		{
			log.debug("PB Exporter: plugin is shutting down, Adventure Log was not saved");
		}
	}

	private List<String> readScrollLines()
	{
		Widget parent = client.getWidget(InterfaceID.Journalscroll.TEXTLAYER);
		if (parent == null)
		{
			return null;
		}

		Widget[] children = parent.getStaticChildren();
		if (children == null)
		{
			return null;
		}

		List<String> lines = new ArrayList<>(children.length);
		for (Widget child : children)
		{
			String text = child == null ? null : child.getText();
			lines.add(text == null
				? ""
				: Text.removeTags(text).replace('\u00a0', ' ').trim());
		}
		return lines;
	}


	private String readAdventureLogOwner()
	{
		String owner = readAdventureLogOwner(InterfaceID.MenuNew.TITLE);
		return owner != null ? owner : readAdventureLogOwner(InterfaceID.Menu.LJ_LAYER2);
	}

	private String readAdventureLogOwner(int componentId)
	{
		Widget container = client.getWidget(componentId);
		if (container == null)
		{
			return null;
		}

		String owner = matchAdventureLogOwner(container.getText());
		if (owner != null)
		{
			return owner;
		}

		Widget[] children = container.getChildren();
		if (children == null)
		{
			return null;
		}
		for (Widget child : children)
		{
			if (child == null)
			{
				continue;
			}
			owner = matchAdventureLogOwner(child.getText());
			if (owner != null)
			{
				return owner;
			}
		}
		return null;
	}

	private static String matchAdventureLogOwner(String text)
	{
		if (text == null)
		{
			return null;
		}

		Matcher matcher = ADVENTURE_LOG_TITLE_PATTERN.matcher(Text.removeTags(text));
		return matcher.find() ? matcher.group(1).trim() : null;
	}

	private void logAdv(String message)
	{
		if (ADV_LOG_DIAGNOSTICS)
		{
			log.info("PB Exporter: {}", message);
		}
		else
		{
			log.debug("PB Exporter: {}", message);
		}
	}

	private boolean cachePlayer(Session session)
	{
		assert client.isClientThread();

		Player player = client.getLocalPlayer();
		String rsProfile = configManager.getRSProfileKey();
		if (player == null || rsProfile == null || rsProfile.trim().isEmpty())
		{
			return false;
		}

		String nickname = player.getName();
		if (nickname == null)
		{
			return false;
		}

		nickname = nickname.replace('\u00a0', ' ').trim();
		if (nickname.isEmpty())
		{
			return false;
		}

		if (!nickname.equals(session.currentNickname) ||
			!rsProfile.equals(session.currentRsProfile))
		{
			log.debug("PB Exporter: cached player {}", nickname);
		}

		session.currentNickname = nickname;
		session.currentRsProfile = rsProfile;
		return true;
	}


	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		Session session = activeSession;
		if (session == null ||
			!PbExporterConfig.GROUP.equals(event.getGroup()) ||
			!"copyRawData".equals(event.getKey()) ||
			!Boolean.parseBoolean(event.getNewValue()))
		{
			return;
		}

		try
		{
			clientThread.invokeLater(() ->
			{
				if (activeSession != session)
				{
					return;
				}

				initializeSession(session);
				try
				{
					copyPersonalBestsToClipboard(session);
				}
				catch (RuntimeException e)
				{
					log.warn("PB Exporter: could not prepare clipboard export", e);
				}
			});
		}
		finally
		{
			configManager.setConfiguration(
				PbExporterConfig.GROUP,
				"copyRawData",
				false
			);
		}
	}

	private void copyPersonalBestsToClipboard(Session session)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			log.warn("PB Exporter: cannot copy PBs while logged out");
			return;
		}

		if (!cachePlayer(session))
		{
			log.warn("PB Exporter: player or RS profile is not available");
			return;
		}

		JsonObject payload = buildPayload(session, session.currentNickname, session.currentRsProfile);
		String json = session.exportGson.toJson(payload);
		String nickname = session.currentNickname;
		int pbCount = payload.getAsJsonArray("personal_bests").size();

		SwingUtilities.invokeLater(() ->
		{
			if (activeSession != session)
			{
				return;
			}

			try
			{
				Toolkit.getDefaultToolkit().getSystemClipboard()
					.setContents(new StringSelection(json), null);
				log.info(
					"PB Exporter: copied {} personal bests for {} to clipboard",
					pbCount,
					nickname
				);
			}
			catch (IllegalStateException | HeadlessException | SecurityException e)
			{
				log.warn("PB Exporter: clipboard is unavailable; try copying again", e);
			}
		});
	}

	private void uploadPersonalBestsIfAllowed(
		Session session,
		String nickname,
		String rsProfile)
	{
		assert client.isClientThread();

		if (activeSession != session)
		{
			return;
		}

		if (nickname == null || nickname.trim().isEmpty() ||
			rsProfile == null || rsProfile.trim().isEmpty())
		{
			log.warn("PB Exporter: cached player or RS profile is not available");
			return;
		}

		String serverUrl = config.serverUrl().trim();
		String token = config.apiToken().trim();
		if (serverUrl.isEmpty() || token.isEmpty())
		{
			log.debug("PB Exporter: automatic upload is not configured");
			return;
		}

		HttpUrl url = HttpUrl.parse(serverUrl);

		if (url == null)
		{
			log.warn("PB Exporter: Server URL must be a valid URL");
			return;
		}

		boolean localhost =
			"127.0.0.1".equals(url.host()) ||
			"localhost".equalsIgnoreCase(url.host());

		if (!url.isHttps() && !localhost)
		{
			log.warn("PB Exporter: Server URL must use HTTPS");
			return;
		}

		if (!url.username().isEmpty() || !url.password().isEmpty())
		{
			log.warn("PB Exporter: Server URL must not contain a username or password");
			return;
		}

		String uploadKey = normalizeNickname(nickname);
		if (session.uploads.containsKey(uploadKey))
		{
			log.debug("PB Exporter: upload already in progress for {}", nickname);
			return;
		}

		long now = System.currentTimeMillis();
		long lastUpload = getLastUploadTime(nickname);
		long elapsed = now - lastUpload;
		if (lastUpload > 0 && elapsed < UPLOAD_COOLDOWN_MS)
		{
			long remaining = UPLOAD_COOLDOWN_MS - elapsed;
			log.debug(
				"PB Exporter: upload skipped for {}. Cooldown remaining: {} minutes",
				nickname,
				TimeUnit.MILLISECONDS.toMinutes(remaining)
			);
			return;
		}

		JsonObject payload = buildPayload(session, nickname, rsProfile);
		if (payload.getAsJsonArray("personal_bests").size() == 0)
		{
			log.debug("PB Exporter: no selected personal bests to upload for {}", nickname);
			return;
		}

		sendToServer(session, url, token, nickname, uploadKey, payload);
	}

	private void sendToServer(
		Session session,
		HttpUrl serverUrl,
		String token,
		String nickname,
		String uploadKey,
		JsonObject payload)
	{
		final Call requestCall;
		try
		{
			String json = session.exportGson.toJson(payload);
			RequestBody body = RequestBody.create(JSON, json);
			Request request = new Request.Builder()
				.url(serverUrl)
				.header("Authorization", "Bearer " + token)
				.header("X-RuneScape-Name", nickname)
				.post(body)
				.build();
			requestCall = session.uploadClient.newCall(request);
		}
		catch (IllegalArgumentException e)
		{
			log.warn("PB Exporter: invalid URL, API Token or nickname; request was not sent");
			return;
		}

		if (session.uploads.putIfAbsent(uploadKey, requestCall) != null)
		{
			return;
		}

		if (activeSession != session)
		{
			session.uploads.remove(uploadKey, requestCall);
			requestCall.cancel();
			return;
		}

		log.info(
			"PB Exporter: sending {} personal bests for {}",
			payload.getAsJsonArray("personal_bests").size(),
			nickname
		);

		try
		{
			requestCall.enqueue(new Callback()
			{
				@Override
				public void onFailure(Call call, IOException e)
				{
					clientThread.invokeLater(() ->
					{
						try
						{
							if (activeSession == session && !call.isCanceled())
							{
								log.warn(
									"PB Exporter: upload failed for {} ({})",
									nickname,
									e.getClass().getSimpleName()
								);
							}
						}
						finally
						{
							session.uploads.remove(uploadKey, call);
						}
					});
				}

				@Override
				public void onResponse(Call call, Response response)
				{
					final int statusCode;
					try (Response r = response)
					{
						statusCode = r.code();
					}
					long completedAt = System.currentTimeMillis();

					clientThread.invokeLater(() ->
					{
						try
						{
							if (activeSession != session)
							{
								return;
							}

							if (statusCode >= 200 && statusCode < 300)
							{
								setLastUploadTime(nickname, completedAt);
								log.info(
									"PB Exporter: sent successfully for {}. HTTP {}",
									nickname,
									statusCode
								);
							}
							else
							{
								log.warn(
									"PB Exporter: server rejected upload for {}. HTTP {}",
									nickname,
									statusCode
								);
							}
						}
						finally
						{
							session.uploads.remove(uploadKey, call);
						}
					});
				}
			});
		}
		catch (RuntimeException e)
		{
			session.uploads.remove(uploadKey, requestCall);
			requestCall.cancel();
			log.warn(
				"PB Exporter: could not schedule upload for {} ({})",
				nickname,
				e.getClass().getSimpleName()
			);
		}
	}

	private long getLastUploadTime(String nickname)
	{
		String value = configManager.getConfiguration(
			PbExporterConfig.GROUP,
			getLastUploadKey(nickname)
		);
		if (value == null)
		{
			return 0L;
		}

		try
		{
			return Long.parseLong(value);
		}
		catch (NumberFormatException e)
		{
			return 0L;
		}
	}

	private void setLastUploadTime(String nickname, long timestamp)
	{
		configManager.setConfiguration(
			PbExporterConfig.GROUP,
			getLastUploadKey(nickname),
			timestamp
		);
	}

	private String getLastUploadKey(String nickname)
	{
		return LAST_UPLOAD_PREFIX + normalizeNickname(nickname);
	}

	private String normalizeNickname(String nickname)
	{
		return nickname
			.replace('\u00a0', ' ')
			.trim()
			.toLowerCase(Locale.ROOT)
			.replace('-', ' ')
			.replace('_', ' ')
			.replaceAll("\\s+", "_");
	}

	private static final class Session
	{
		private final Gson exportGson;
		private final OkHttpClient uploadClient;
		private final PbStore pbStore;
		private final ExecutorService ioExecutor;

		private final Map<String, Call> uploads = new ConcurrentHashMap<>();

		private boolean initialized;
		private boolean wasLoggedIn;
		private boolean worldHopInProgress;
		private String currentNickname;
		private String currentRsProfile;

		// Adventure Log state
		private boolean advLogLoaded;
		private boolean scrollLoaded;
		private String pohOwner;

		// Fractured Archive Alliance Log state
		private int tfaTicks;
		private String tfaSeen;

		private Session(
			Gson exportGson,
			OkHttpClient uploadClient,
			PbStore pbStore,
			ExecutorService ioExecutor)
		{
			this.exportGson = exportGson;
			this.uploadClient = uploadClient;
			this.pbStore = pbStore;
			this.ioExecutor = ioExecutor;
		}
	}

	private static boolean isLogSourced(String boss)
	{
		return AdventureLogParser.isRaid(boss) || AdventureLogParser.TFA_BOSS.equals(boss);
	}

	private JsonObject buildPayload(Session session, String nickname, String rsProfile)
	{
		List<String> pbKeys =
			configManager.getRSProfileConfigurationKeys(
				"personalbest",
				rsProfile,
				""
			);

		Map<String, Double> foundPbs =
			new HashMap<>();

		for (String key : pbKeys)
		{
			Double time =
				configManager.getConfiguration(
					"personalbest",
					rsProfile,
					key,
					double.class
				);

			if (time == null || !Double.isFinite(time) || time < 0)
			{
				continue;
			}

			PbName parsed =
				parsePbName(key);

			String boss =
				parsed.boss
					.trim()
					.toLowerCase(Locale.ROOT);

			if (isLogSourced(boss))
			{
				continue;
			}

			String scale =
				parsed.scale == null
					? ""
					: parsed.scale
						.trim()
						.toLowerCase(Locale.ROOT);

			foundPbs.put(
				boss + "\n" + scale,
				time
			);
		}


		try
		{
			for (PbRecord record : session.pbStore.read(nickname))
			{
				if (record == null
					|| record.boss == null
					|| !isLogSourced(record.boss)
					|| !Double.isFinite(record.time)
					|| record.time <= 0)
				{
					continue;
				}

				foundPbs.put(
					record.boss + "\n" + (record.scale == null ? "" : record.scale),
					record.time
				);
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("PB Exporter: could not read pbs.json, raids are not included", e);
		}

		JsonArray personalBests =
			new JsonArray();

		for (Map.Entry<String, List<String>> entry :
			EXPORT_LIST.entrySet())
		{
			String boss =
				entry.getKey();

			List<String> scales =
				entry.getValue();


			if (scales.isEmpty())
			{
				Double time =
					foundPbs.get(
						boss + "\n"
					);

				if (time == null)
				{
					continue;
				}

				JsonObject pb =
					new JsonObject();

				pb.addProperty(
					"boss",
					boss
				);

				pb.add(
					"scale",
					com.google.gson.JsonNull.INSTANCE
				);

				pb.addProperty(
					"time",
					time
				);

				personalBests.add(pb);

				continue;
			}

			for (String scale : scales)
			{
				Double time =
					foundPbs.get(
						boss + "\n" + scale
					);

				if (time == null)
				{
					continue;
				}

				JsonObject pb =
					new JsonObject();

				pb.addProperty(
					"boss",
					boss
				);

				pb.addProperty(
					"scale",
					scale
				);

				pb.addProperty(
					"time",
					time
				);

				personalBests.add(pb);
			}
		}


		JsonObject root =
			new JsonObject();

		root.add(
			"personal_bests",
			personalBests
		);

		return root;
	}


	private PbName parsePbName(String key)
	{
		Matcher matcher =
			SCALE_PATTERN.matcher(key);

		if (matcher.matches())
		{
			return new PbName(
				matcher.group("boss"),
				matcher.group("scale")
			);
		}

		return new PbName(
			key,
			null
		);
	}


	private static class PbName
	{
		private final String boss;
		private final String scale;

		private PbName(
			String boss,
			String scale)
		{
			this.boss = boss;
			this.scale = scale;
		}
	}
}

package com.pbexporter;

import java.util.Objects;

final class PbRecord
{
	final String boss;
	final String scale;
	final double time;

	PbRecord(String boss, String scale, double time)
	{
		this.boss = boss;
		this.scale = scale;
		this.time = time;
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof PbRecord))
		{
			return false;
		}
		PbRecord other = (PbRecord) o;
		return Double.compare(time, other.time) == 0
			&& Objects.equals(boss, other.boss)
			&& Objects.equals(scale, other.scale);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(boss, scale, time);
	}

	@Override
	public String toString()
	{
		return boss + (scale == null ? "" : " " + scale) + "=" + time;
	}
}

package com.pbexporter;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.gson.annotations.SerializedName;
import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.nio.file.NoSuchFileException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

@Slf4j
final class PbStore
{
	private static final int VERSION = 1;

	private static final String FILE_NAME = "pbs.json";

	private final Filepath dir;
	private final Gson gson;
	private final Object lock = new Object();

	/** @param dir the plugin data directory, i.e. {@code Plugin#getPluginDirectory()} */
	PbStore(Filepath dir, Gson gson)
	{
		this.dir = dir;
		this.gson = gson;
	}

	void replaceBosses(String nickname, Set<String> bosses, List<PbRecord> records) throws IOException
	{
		synchronized (lock)
		{
			PbFile data = load();

			PlayerPbs player = data.players.get(nickname);
			if (player == null)
			{
				player = new PlayerPbs();
				data.players.put(nickname, player);
			}
			if (player.personalBests == null)
			{
				player.personalBests = new ArrayList<>();
			}

			player.personalBests.removeIf(r -> r == null || bosses.contains(r.boss));
			player.personalBests.addAll(records);
			player.personalBests.sort((a, b) ->
				String.valueOf(a.boss).compareTo(String.valueOf(b.boss)));
			player.updatedAt = System.currentTimeMillis();

			save(data);
		}
	}

	List<PbRecord> read(String nickname) throws IOException
	{
		synchronized (lock)
		{
			PbFile data = load();
			for (Map.Entry<String, PlayerPbs> entry : data.players.entrySet())
			{
				PlayerPbs player = entry.getValue();
				if (entry.getKey().equalsIgnoreCase(nickname)
					&& player != null && player.personalBests != null)
				{
					return new ArrayList<>(player.personalBests);
				}
			}
			return new ArrayList<>();
		}
	}

	private PbFile load() throws IOException
	{
		Filepath file = dir.joinSegment(FILE_NAME);

		try (BufferedReader reader = file.openBufferedReader())
		{
			PbFile data = gson.fromJson(reader, PbFile.class);
			if (data != null && data.players != null)
			{
				return data;
			}
			log.warn("PB Exporter: {} has an unexpected structure", FILE_NAME);
		}
		catch (NoSuchFileException e)
		{
			return new PbFile();
		}
		catch (JsonParseException e)
		{
			log.warn("PB Exporter: {} is not valid JSON: {}", FILE_NAME, e.toString());
		}

		// Only reached for broken content (a plain IOException is propagated
		// and the write is skipped, so we never throw away good data because
		// of e.g. a temporarily locked file). The data is rebuilt when the
		// Adventure Log / Alliance Log is opened again.
		return new PbFile();
	}

	private void save(PbFile data) throws IOException
	{
		if (!dir.exists())
		{
			dir.createDirectories();
		}

		Filepath file = dir.joinSegment(FILE_NAME);
		try (BufferedWriter writer = file.openBufferedWriter())
		{
			gson.toJson(data, writer);
		}
	}

	private static final class PbFile
	{
		int version = VERSION;
		Map<String, PlayerPbs> players = new LinkedHashMap<>();
	}

	private static final class PlayerPbs
	{
		@SerializedName("updated_at")
		long updatedAt;

		@SerializedName("personal_bests")
		List<PbRecord> personalBests = new ArrayList<>();
	}
}

package com.pbexporter;

import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;


final class TfaBoard
{
	/** Interface group of the Alliance Log. */
	static final int GROUP = 979;

	/** Component with the table texts as dynamic children. */
	private static final int COMPONENT = 34;

	private TfaBoard()
	{
	}

	static List<String> readTexts(Client client)
	{
		Widget table = client.getWidget(GROUP, COMPONENT);
		if (table == null)
		{
			return null;
		}

		Widget[] children = table.getChildren();
		if (children == null)
		{
			return null;
		}

		List<String> texts = new ArrayList<>(children.length);
		for (Widget child : children)
		{
			String text = child == null ? null : child.getText();
			texts.add(text == null ? "" : Text.removeTags(text).replace('\u00a0', ' ').trim());
		}
		return texts;
	}
}

